import functools
import pytest
from fastapi import FastAPI
from fastapi.dependencies.utils import get_typed_signature
from typing import List

class MyModel:
    pass

def get_items() -> List['MyModel']:
    return []

@functools.wraps(get_items)
def wrapped_get_items():
    return get_items()

def test_wrapped_method_type_inference():
    # This is where it should fail if not fixed
    # get_typed_signature should be able to resolve 'MyModel'
    # using the globals of the original wrapped function.
    sig = get_typed_signature(wrapped_get_items)
    assert sig.return_annotation == List[MyModel]

    # Testing with a route
    app = FastAPI()

    def read_items(q: str = 'foo'):
        return {'q': q}

    @functools.wraps(read_items)
    def wrapped_read_items(q: str = 'foo'):
        return read_items(q)

    sig_route = get_typed_signature(wrapped_read_items)
    assert 'q' in sig_route.parameters
    assert sig_route.parameters['q'].annotation == str

